    static long checks;static void eq(Object a,Object b){checks++;if(!Objects.equals(a,b))throw new AssertionError(a+" != "+b);}
    static void bad(Runnable r){checks++;try{r.run();}catch(IllegalArgumentException e){return;}throw new AssertionError("invalid accepted");}
    static List<ListVariants.Node> nodes(int[] a){List<ListVariants.Node> list=new ArrayList<>();for(int x:a)list.add(new ListVariants.Node(x));for(int i=1;i<list.size();i++)list.get(i-1).next=list.get(i);return list;}
    static List<ListVariants.Node> materialize(ListVariants.Node head){List<ListVariants.Node> out=new ArrayList<>();Set<ListVariants.Node> seen=Collections.newSetFromMap(new IdentityHashMap<>());for(var p=head;p!=null;p=p.next){if(!seen.add(p))throw new AssertionError("cycle");out.add(p);}return out;}
    public static void main(String[] args){Random r=new Random(20261025);
        for(int z=0;z<3000;z++){int[] a=r.ints(r.nextInt(40),-5,6).toArray();for(boolean recursive:new boolean[]{false,true}){List<ListVariants.Node> original=nodes(a),expected=new ArrayList<>(original);expected.sort(Comparator.comparingInt(n->n.value));ListVariants.Node head=original.isEmpty()?null:original.get(0);eq(materialize(recursive?ListVariants.sortRecursive(head):ListVariants.sortBottomUp(head)),expected);}
            if(a.length>0)for(int method=0;method<3;method++){List<ListVariants.Node> original=nodes(a),expected=new ArrayList<>(original);int n=1+r.nextInt(a.length);expected.remove(a.length-n);ListVariants.Node head=switch(method){case 0->ListVariants.removeNthTwoPass(original.get(0),n);case 1->ListVariants.removeNthStack(original.get(0),n);default->ListVariants.removeNthRecursive(original.get(0),n);};eq(materialize(head),expected);}
            BigInteger x=new BigInteger(200,r),y=new BigInteger(200,r);String expected=x.add(y).toString(36);ListVariants.Node fx=number(x.toString(36),false),fy=number(y.toString(36),false),rx=number(x.toString(36),true),ry=number(y.toString(36),true);
            eq(text(ListVariants.addBase36Forward(fx,fy),false),expected);eq(text(ListVariants.addBase36Reverse(rx,ry),true),expected);eq(text(fx,false),x.toString(36));eq(text(fy,false),y.toString(36));eq(text(rx,true),x.toString(36));eq(text(ry,true),y.toString(36));
        }
        var list=nodes(new int[]{1,2,3});ListVariants.Node p=list.get(1),removed=list.get(2);ListVariants.deleteGivenNonTail(p);eq(p==list.get(1),true);eq(p.value,3);eq(p.next,null);eq(removed.value,3);
        bad(()->ListVariants.deleteGivenNonTail(p));bad(()->ListVariants.deleteGivenNonTail(null));
        for(int method=0;method<3;method++){var original=nodes(new int[]{1,2});int m=method;bad(()->{switch(m){case 0->ListVariants.removeNthTwoPass(original.get(0),3);case 1->ListVariants.removeNthStack(original.get(0),3);default->ListVariants.removeNthRecursive(original.get(0),3);}});eq(materialize(original.get(0)),original);}
        eq(text(ListVariants.addBase36Reverse(null,null),true),"0");eq(text(ListVariants.addBase36Forward(number("000",false),number("00",false)),false),"0");eq(text(ListVariants.addBase36Reverse(number("000",true),number("00",true)),true),"0");
        var invalid=new ListVariants.Node(36);bad(()->ListVariants.addBase36Reverse(invalid,null));var cycle=new ListVariants.Node(1);cycle.next=cycle;bad(()->ListVariants.addBase36Forward(cycle,null));
        for(int d=0;d<36;d++)eq(ListVariants.base36Digit(ListVariants.base36Symbol(d)),d);bad(()->ListVariants.base36Digit('A'));
        int[] longList=new int[100000];for(int i=0;i<longList.length;i++)longList[i]=longList.length-i;var original=nodes(longList);var sorted=materialize(ListVariants.sortBottomUp(original.get(0)));for(int i=0;i<sorted.size();i++)eq(sorted.get(i).value,i+1);
        System.out.println("ListVariantsTest PASS "+checks);
    }
    static ListVariants.Node number(String s,boolean reverse){int[] digits=s.chars().map(c->ListVariants.base36Digit((char)c)).toArray();if(reverse)for(int i=0,j=digits.length-1;i<j;i++,j--){int t=digits[i];digits[i]=digits[j];digits[j]=t;}return nodes(digits).get(0);}
    static String text(ListVariants.Node n,boolean reverse){StringBuilder s=new StringBuilder();for(var p:nodesOf(n))s.append(ListVariants.base36Symbol(p.value));return reverse?s.reverse().toString():s.toString();}
    static List<ListVariants.Node> nodesOf(ListVariants.Node n){return materialize(n);}
}

import java.util.*;
public final class SortAlternatingList {
    public static final class Node {final int value;Node next;Node(int value){this.value=value;}}
    public static Node sort(Node head){
        Node slow=head,fast=head;
        while(fast!=null&&fast.next!=null){slow=slow.next;fast=fast.next.next;if(slow==fast)throw new IllegalArgumentException("cycle");}
        Node oddPrevious=null,evenPrevious=null;boolean odd=true;
        for(Node p=head;p!=null;p=p.next){
            if(odd){if(oddPrevious!=null&&oddPrevious.value>p.value)throw new IllegalArgumentException("odd positions must increase");oddPrevious=p;}
            else{if(evenPrevious!=null&&evenPrevious.value<p.value)throw new IllegalArgumentException("even positions must decrease");evenPrevious=p;}odd=!odd;
        }
        Node oddDummy=new Node(0),evenDummy=new Node(0),ot=oddDummy,et=evenDummy;odd=true;
        for(Node p=head;p!=null;){Node next=p.next;p.next=null;if(odd){ot.next=p;ot=p;}else{et.next=p;et=p;}odd=!odd;p=next;}
        Node reversed=null,p=evenDummy.next;
        while(p!=null){Node next=p.next;p.next=reversed;reversed=p;p=next;}
        Node a=oddDummy.next,b=reversed,dummy=new Node(0),tail=dummy;
        while(a!=null&&b!=null){if(a.value<=b.value){tail.next=a;a=a.next;}else{tail.next=b;b=b.next;}tail=tail.next;}
        tail.next=a!=null?a:b;return dummy.next;
    }
    private static void verify(int[] values){
        Set<Node> ids=Collections.newSetFromMap(new IdentityHashMap<>());Node head=null;
        for(int i=values.length-1;i>=0;i--){Node n=new Node(values[i]);n.next=head;head=n;ids.add(n);}
        int[] expect=values.clone();Arrays.sort(expect);Node out=sort(head);
        for(int v:expect){if(out==null||out.value!=v||!ids.remove(out))throw new AssertionError();out=out.next;}
        if(out!=null||!ids.isEmpty())throw new AssertionError();
    }
    public static void main(String[] args){
        Random r=new Random(1671);
        for(int t=0;t<10000;t++){
            int n=r.nextInt(81);int[] a=new int[(n+1)/2],b=new int[n/2],input=new int[n];
            for(int i=0;i<a.length;i++)a[i]=r.nextInt(101)-50;for(int i=0;i<b.length;i++)b[i]=r.nextInt(101)-50;Arrays.sort(a);Arrays.sort(b);
            for(int i=0;i<n;i++)input[i]=(i%2==0)?a[i/2]:b[b.length-1-i/2];verify(input);
